def _fit_phase(phase: str, variant: str, task, workers: int, log_name: str) -> list[dict]:
    todo = [(m, h, s) for m, h in MC.PANEL for s in MC.SEEDS]
    results = []
    if workers > 1:
        ctx = mp.get_context('spawn')
        with ProcessPoolExecutor(max_workers=workers, mp_context=ctx, initializer=_init_worker) as pool:
            for res in pool.map(task, todo):
                results.append(res)
                print(f"  {phase} fit {res['cell']} seed{res['seed']}: {res['status']}", flush=True)
    else:
        for args in todo:
            res = task(args)
            results.append(res)
            print(f"  {phase} fit {res['cell']} seed{res['seed']}: {res['status']}", flush=True)
    U.json_dump(EVID / log_name, {'schema': 'hch_v44_o1_matched_fit_log.v1', 'protocol_id': MC.PROTOCOL_ID, 'phase': phase, 'variant': variant, 'n_registered_new_fits': len(todo), 'n_fitted': sum((1 for r in results if r['status'] == 'fitted')), 'n_skipped_existing': sum((1 for r in results if r['status'] == 'skipped_existing')), 'attempts_per_coordinate': {f"{r['cell']}__seed{r['seed']}": 1 for r in results}, 'no_retry': len(results) == len(todo), 'workers': int(workers), 'finished': dt.datetime.now(dt.timezone.utc).isoformat(), 'results': results})
    return results
